<style>
:root{color-scheme:light;--doc-ink:#18211d;--doc-muted:#66736d;--doc-line:#d8e1dc;--doc-soft:#f3f7f4;--doc-accent:#176a43;--doc-accent-soft:#eaf5ee;--doc-warn:#8b5510;--doc-warn-soft:#fff6e7}
*{box-sizing:border-box}
html{background:#edf1ee}
body{font:13px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;margin:24px auto;padding:30px;color:var(--doc-ink);max-width:960px;background:#fff;box-shadow:0 12px 40px rgba(20,44,30,.1)}
h1{font-size:19px;line-height:1.2;margin:0;letter-spacing:-.02em}.m{color:var(--doc-muted);font-size:11px}
.head{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;border-bottom:2px solid var(--doc-accent);padding-bottom:14px}
.doc{text-align:right;min-width:170px}.doc h2{margin:1px 0 4px;font-size:23px;letter-spacing:.025em;line-height:1.15}.doc .m{margin-top:3px}
.kv{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px 18px;margin:14px 0}.kv div{min-width:0}
.kv div span,.lbl{display:block;font-size:10px;text-transform:uppercase;color:var(--doc-muted);letter-spacing:.055em;font-weight:700;margin-bottom:2px}
table{width:100%;border-collapse:collapse;margin-top:8px}td,th{padding:8px 9px;border-bottom:1px solid var(--doc-line);text-align:left;vertical-align:top}th{font-size:10px;color:#45544c;background:var(--doc-soft);text-transform:uppercase;letter-spacing:.045em}td.r,th.r{text-align:right;font-variant-numeric:tabular-nums}tfoot td{font-weight:700;border-top:2px solid var(--doc-ink)}
.sig{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:44px}.sig div{border-top:1px solid #88948e;padding-top:6px;font-size:11px;min-height:34px}
.stamp{display:inline-block;border:1px solid #9da9a2;border-radius:999px;padding:3px 10px;font-weight:750;font-size:10px;margin-top:5px;text-transform:uppercase;letter-spacing:.045em;background:var(--doc-soft);color:#405148}.status-definite,.status-completed{background:#e7f4eb;border-color:#9dc9a9;color:#165a34}.status-tentative{background:#fff5df;border-color:#efcd82;color:#80500a}.status-cancelled,.status-lost{background:#fceceb;border-color:#e4b1ad;color:#8d312a}.status-enquiry{background:#eef1f3;border-color:#cbd3d8;color:#46535b}
.fn{border:1px solid var(--doc-line);border-radius:9px;margin:15px 0;overflow:hidden;break-inside:avoid-page;page-break-inside:avoid}.fn h3{margin:0;padding:8px 11px;background:#20372b;color:#fff;font-size:13px;display:flex;justify-content:space-between;gap:16px}.fn h3 span:last-child{text-align:right;font-weight:600;white-space:nowrap}
.fn .body{padding:10px 12px}.dept{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px 20px;margin-top:7px}.dept div{border-top:1px solid var(--doc-line);padding-top:6px;min-width:0}
.pre{white-space:pre-line}.big{font-size:20px;font-weight:750}.muted{color:var(--doc-muted)}.note{font-size:11px;color:#536159}
.document-actions{max-width:960px;margin:0 auto 10px;display:flex;justify-content:flex-end;gap:8px}.document-actions button{appearance:none;border:1px solid #c5d1c9;border-radius:8px;padding:9px 13px;background:#fff;color:#20372b;font:inherit;font-weight:700;cursor:pointer}.document-actions button:hover{background:var(--doc-soft)}.document-actions button:focus-visible{outline:3px solid #86c39c;outline-offset:2px}
.quote-recipient{display:grid;grid-template-columns:1.2fr 1fr;gap:18px;margin:16px 0 10px;padding:14px 16px;border:1px solid var(--doc-line);border-radius:10px;background:#fbfdfb}.quote-recipient h2{font-size:16px;line-height:1.3;margin:2px 0 3px}.quote-recipient .quote-field-label{display:block;color:var(--doc-muted);font-size:10px;text-transform:uppercase;letter-spacing:.055em;font-weight:750}.quote-event-title{font-weight:700}.quote-message{margin:12px 0;color:#35443b}.quote-pricing-note{margin:8px 2px 12px;color:var(--doc-muted);font-size:10px}.quote-table-hint{display:none;margin:6px 0;color:var(--doc-muted);font-size:10px}.quote-option{margin:11px 0;padding:9px 12px;border:1px solid #f1d29a;border-radius:8px;background:var(--doc-warn-soft);color:#70420c;font-weight:650}.quote-table-wrap{width:100%;overflow-x:auto}.quote-table{table-layout:fixed;margin-top:10px}.quote-table th:nth-child(1){width:21%}.quote-table th:nth-child(2){width:18%}.quote-table th:nth-child(3){width:11%}.quote-table th:nth-child(4){width:34%}.quote-table th:nth-child(5){width:16%}.quote-table tbody tr{break-inside:avoid-page;page-break-inside:avoid}.quote-table td{overflow-wrap:anywhere}.quote-function-name{font-weight:750}.quote-function-meta{display:block;margin-top:3px}.quote-setup{display:block;color:var(--doc-muted);font-size:11px;margin-top:3px}.quote-pax{font-weight:750;font-variant-numeric:tabular-nums}.quote-pax-note{display:block;font-size:9px;color:var(--doc-muted)}.quote-menu-row td{padding-top:5px;padding-bottom:8px;background:#fbfdfb}.quote-menu-label{font-weight:750;color:#45544c}.quote-summary-label{font-weight:500;color:#405148}.quote-total-row td{font-size:14px;background:var(--doc-accent-soft);border-top:1px solid #b8d9c2}.quote-total-row td:last-child{color:#145b37;font-size:16px}.quote-support{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:15px}.quote-support-card{border:1px solid var(--doc-line);border-radius:9px;padding:11px 13px;background:#fff}.quote-support-card>span{display:block;color:var(--doc-muted);font-size:10px;text-transform:uppercase;letter-spacing:.055em;font-weight:750;margin-bottom:5px}.quote-support-card p{margin:0}.quote-support-card strong{font-size:15px}.quote-terms{margin-top:13px;padding:12px 14px;border:1px solid var(--doc-line);border-radius:9px;background:var(--doc-soft)}.quote-terms .lbl{margin-bottom:5px}.quote-signatures{grid-template-columns:1fr 1fr;margin-top:44px}.quote-signatures div{border:0;padding:0;min-height:0;font-size:11px}.quote-signing-space{display:block;height:36px;border-bottom:1px solid #88948e;margin-bottom:5px}.quote-signatory{display:block;min-height:15px;font-weight:650}.quote-signature-meta{display:block;color:var(--doc-muted);font-size:10px}.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@page{size:A4 portrait;margin:13mm 12mm 14mm}
@media(max-width:700px){body{margin:12px;padding:18px}.document-actions{margin:0 12px 8px}.head{gap:12px}.kv{grid-template-columns:repeat(2,minmax(0,1fr))}.dept{grid-template-columns:1fr}.quote-recipient{grid-template-columns:1fr}.quote-table-hint{display:block}.quote-table{min-width:720px}.quote-support{grid-template-columns:1fr}.fn h3{flex-direction:column;gap:2px}.fn h3 span:last-child{text-align:left;white-space:normal}}
@media print{html{background:#fff}body{max-width:none;width:auto;margin:0;padding:0;box-shadow:none;font-size:10pt;line-height:1.4;color:#111;-webkit-print-color-adjust:exact;print-color-adjust:exact}.document-actions,button,.noprint{display:none!important}.head{break-after:avoid-page}.fn{break-inside:avoid-page;page-break-inside:avoid}.fn h3{background:#20372b!important;color:#fff!important}.quote-recipient,.quote-support-card,.quote-terms{break-inside:avoid-page;page-break-inside:avoid}.quote-table thead{display:table-header-group}.quote-table tfoot{display:table-row-group}.quote-table tr{break-inside:avoid-page;page-break-inside:avoid}.quote-option{break-inside:avoid-page;page-break-inside:avoid}.sig{break-inside:avoid-page;page-break-inside:avoid}.quote-table{min-width:0}.quote-table td,.quote-table th{padding:6px 6px;font-size:9pt}.quote-table th{font-size:8pt}}
</style>
